/**
 * The runtime of packages generated by purecrate-ts. Every generated package
 * carries its own copy (src/purecrate-runtime.ts). The brands are keyed by
 * string, not by `unique symbol`, so an `I32` or a `Uuid` from one package's
 * copy is the same type as another's and values pass between packages.
 *
 * A package's copy keeps only what its code uses: the region and needs
 * comments below mark code kept when any use they list is found in the
 * package, and are left out of the copy (crates/pack/src/trim.rs).
 */
// #region Result
/** Rust's `Result`, as every generated package reads and builds it. */
export type Result<T, E> =
  | Readonly<{ kind: "Ok"; value: T }>
  | Readonly<{ kind: "Err"; error: E }>;

export const Result = {
  ok: <T, E = never>(value: T): Result<T, E> => ({ kind: "Ok", value }),
  err: <T = never, E = never>(error: E): Result<T, E> => ({ kind: "Err", error }),
  isOk: <T, E>(r: Result<T, E>): r is Readonly<{ kind: "Ok"; value: T }> => r.kind === "Ok",
  isErr: <T, E>(r: Result<T, E>): r is Readonly<{ kind: "Err"; error: E }> => r.kind === "Err",
} as const;
// #endregion

/**
 * A domain panic: overflow, division by zero, a shift out of range, or an
 * index/slice Rust would panic on. `message` is Rust's panic text. Named
 * `Panic` so `instanceof` works across copies of this file (`Symbol.for`).
 */
const PANIC = Symbol.for("purecrate.Panic");

export class Panic extends Error {
  readonly [PANIC] = true;
  constructor(message: string) {
    super(message);
    this.name = "Panic";
  }
  static [Symbol.hasInstance](value: unknown): boolean {
    return typeof value === "object" && value !== null && PANIC in (value as object);
  }
}

/** The `default` of a `switch` that names every variant: unreachable. */
export const assertNever = (_x: never): never => {
  throw new Error("unexpected variant");
};

export type I8 = number & { readonly "purecrate.I8": true }; // #needs I8
export type I16 = number & { readonly "purecrate.I16": true }; // #needs I16
export type I32 = number & { readonly "purecrate.I32": true }; // #needs I32
export type I64 = bigint & { readonly "purecrate.I64": true }; // #needs I64
export type U8 = number & { readonly "purecrate.U8": true }; // #needs U8
export type U16 = number & { readonly "purecrate.U16": true }; // #needs U16
export type U32 = number & { readonly "purecrate.U32": true }; // #needs U32
export type U64 = bigint & { readonly "purecrate.U64": true }; // #needs U64
export type Usize = number & { readonly "purecrate.Usize": true }; // #needs Usize
export type F32 = number & { readonly "purecrate.F32": true }; // #needs F32
export type F64 = number & { readonly "purecrate.F64": true }; // #needs F64
// #region Char
/** A Rust `char`: a string of exactly one Unicode scalar value (no lone surrogate). */
export type Char = string & { readonly "purecrate.Char": true };
// #endregion

// #region panic
const panic = (what: string): never => {
  throw new Panic(`attempt to ${what}`);
};
// #endregion

// #region small
const small = <T extends number>(min: number, max: number) => {
  const fit = (n: number, what: string): T =>
    (n < min || n > max ? panic(`${what} with overflow`) : n + 0) as T;
  const of = (value: number): T => {
    if (!Number.isInteger(value)) panic("convert a non-integer");
    return fit(value, "convert");
  };
  return {
    of,
    add: (a: T, b: T): T => fit(a + b, "add"), // #needs op.add
    sub: (a: T, b: T): T => fit(a - b, "subtract"), // #needs op.sub
    mul: (a: T, b: T): T => fit(a * b, "multiply"), // #needs op.mul
    // #region op.div
    div: (a: T, b: T): T =>
      b === 0 ? panic("divide by zero") : fit(Math.trunc(a / b), "divide"),
    // #endregion
    // #region op.rem
    rem: (a: T, b: T): T =>
      b === 0
        ? panic("calculate the remainder with a divisor of zero")
        : ((fit(Math.trunc(a / b), "calculate the remainder"), (a % b) + 0) as T),
    // #endregion
    neg: (a: T): T => fit(-a, "negate"), // #needs op.neg
  } as const;
};
// #endregion

// #region big
const big = <T extends bigint>(min: bigint, max: bigint) => {
  const fit = (n: bigint, what: string): T =>
    (n < min || n > max ? panic(`${what} with overflow`) : n) as T;
  const n = (x: T): bigint => x as bigint; // #needs op.add op.sub op.mul op.div op.rem op.neg
  return {
    of: (value: bigint): T => fit(value, "convert"),
    add: (a: T, b: T): T => fit(n(a) + n(b), "add"), // #needs op.add
    sub: (a: T, b: T): T => fit(n(a) - n(b), "subtract"), // #needs op.sub
    mul: (a: T, b: T): T => fit(n(a) * n(b), "multiply"), // #needs op.mul
    // #region op.div
    div: (a: T, b: T): T =>
      n(b) === 0n ? panic("divide by zero") : fit(n(a) / n(b), "divide"),
    // #endregion
    // #region op.rem
    rem: (a: T, b: T): T =>
      n(b) === 0n
        ? panic("calculate the remainder with a divisor of zero")
        : ((fit(n(a) / n(b), "calculate the remainder"), n(a) % n(b)) as unknown as T),
    // #endregion
    neg: (a: T): T => fit(-n(a), "negate"), // #needs op.neg
  } as const;
};
// #endregion

// #region methods.i8 methods.i16 methods.i32 methods.u8 methods.u16 methods.u32 methods.usize methods.i64 methods.u64
/**
 * The integer methods, from the exact result: `x.checked_add(y)` is it or
 * `null` outside the range, `saturating_*` clamps it, `wrapping_*` keeps its
 * low `bits`, and the others panic outside the range as a debug build does.
 * `lo..=hi` is Rust's range; `to` makes the runtime value, and for `usize`
 * throws above 2^53−1, which a `number` cannot hold (design/01 §3).
 */
const methods = <T extends number | bigint>(r: { lo: bigint; hi: bigint; bits: number; signed: boolean; to: (n: bigint) => T }) => {
  const v = (x: T): bigint => BigInt(x); // #needs m.abs m.pow m.checkedAdd m.checkedSub m.checkedMul m.checkedDiv m.checkedRem m.checkedNeg m.checkedPow m.saturatingAdd m.saturatingSub m.saturatingMul m.saturatingPow m.wrappingAdd m.wrappingSub m.wrappingMul m.wrappingDiv m.wrappingRem m.wrappingNeg m.wrappingPow
  const inRange = (n: bigint): boolean => n >= r.lo && n <= r.hi; // #needs m.abs m.pow m.checkedAdd m.checkedSub m.checkedMul m.checkedDiv m.checkedRem m.checkedNeg m.checkedPow
  const fit = (n: bigint | null, what: string): T => (n !== null && inRange(n) ? r.to(n) : panic(`${what} with overflow`)); // #needs m.abs m.pow
  const checked = (n: bigint | null): T | null => (n !== null && inRange(n) ? r.to(n) : null); // #needs m.checkedAdd m.checkedSub m.checkedMul m.checkedDiv m.checkedRem m.checkedNeg m.checkedPow
  const clamp = (n: bigint): T => r.to(n < r.lo ? r.lo : n > r.hi ? r.hi : n); // #needs m.saturatingAdd m.saturatingSub m.saturatingMul m.saturatingPow
  const wrap = (n: bigint): T => r.to(r.signed ? BigInt.asIntN(r.bits, n) : BigInt.asUintN(r.bits, n)); // #needs m.wrappingAdd m.wrappingSub m.wrappingMul m.wrappingDiv m.wrappingRem m.wrappingNeg m.wrappingPow
  // #region m.pow m.checkedPow m.saturatingPow
  // `a ** e`, or `null` where it is certainly outside the range: a base of
  // magnitude 2 or more to an exponent of `bits` or more.
  const power = (a: bigint, e: number): bigint | null =>
    e === 0 ? 1n : a === 0n || a === 1n ? a : a === -1n ? (e % 2 === 0 ? 1n : -1n) : e >= r.bits ? null : a ** BigInt(e);
  // #endregion
  // #region m.wrappingPow
  const modPower = (a: bigint, e: number): bigint => {
    const m = 1n << BigInt(r.bits);
    let base = BigInt.asUintN(r.bits, a);
    let acc = 1n;
    for (let k = e; k > 0; k = Math.floor(k / 2)) {
      if (k % 2 === 1) acc = (acc * base) % m;
      base = (base * base) % m;
    }
    return acc;
  };
  // #endregion
  const quotient = (a: bigint, b: bigint): bigint | null => (b === 0n ? null : a / b); // #needs m.checkedDiv m.checkedRem
  // #region m.wrappingDiv m.wrappingRem
  const zero = (b: T, what: string): void => {
    if (v(b) === 0n) panic(what);
  };
  // #endregion
  return {
    abs: (a: T): T => fit(v(a) < 0n ? -v(a) : v(a), "negate"), // #needs m.abs
    pow: (a: T, e: U32): T => fit(power(v(a), e), "exponentiate"), // #needs m.pow
    checkedAdd: (a: T, b: T): T | null => checked(v(a) + v(b)), // #needs m.checkedAdd
    checkedSub: (a: T, b: T): T | null => checked(v(a) - v(b)), // #needs m.checkedSub
    checkedMul: (a: T, b: T): T | null => checked(v(a) * v(b)), // #needs m.checkedMul
    checkedDiv: (a: T, b: T): T | null => checked(quotient(v(a), v(b))), // #needs m.checkedDiv
    // #region m.checkedRem
    // `MIN % -1` is `None`: the quotient it comes from overflows.
    checkedRem: (a: T, b: T): T | null =>
      checked(quotient(v(a), v(b))) === null ? null : r.to(v(a) % v(b)),
    // #endregion
    checkedNeg: (a: T): T | null => checked(-v(a)), // #needs m.checkedNeg
    checkedPow: (a: T, e: U32): T | null => checked(power(v(a), e)), // #needs m.checkedPow
    saturatingAdd: (a: T, b: T): T => clamp(v(a) + v(b)), // #needs m.saturatingAdd
    saturatingSub: (a: T, b: T): T => clamp(v(a) - v(b)), // #needs m.saturatingSub
    saturatingMul: (a: T, b: T): T => clamp(v(a) * v(b)), // #needs m.saturatingMul
    // #region m.saturatingPow
    saturatingPow: (a: T, e: U32): T => {
      const n = power(v(a), e);
      return n !== null ? clamp(n) : r.to(v(a) < 0n && e % 2 === 1 ? r.lo : r.hi);
    },
    // #endregion
    wrappingAdd: (a: T, b: T): T => wrap(v(a) + v(b)), // #needs m.wrappingAdd
    wrappingSub: (a: T, b: T): T => wrap(v(a) - v(b)), // #needs m.wrappingSub
    wrappingMul: (a: T, b: T): T => wrap(v(a) * v(b)), // #needs m.wrappingMul
    wrappingDiv: (a: T, b: T): T => (zero(b, "divide by zero"), wrap(v(a) / v(b))), // #needs m.wrappingDiv
    // #region m.wrappingRem
    wrappingRem: (a: T, b: T): T =>
      (zero(b, "calculate the remainder with a divisor of zero"), wrap(v(a) % v(b))),
    // #endregion
    wrappingNeg: (a: T): T => wrap(-v(a)), // #needs m.wrappingNeg
    wrappingPow: (a: T, e: U32): T => wrap(modPower(v(a), e)), // #needs m.wrappingPow
  } as const;
};
// #endregion

// #region minmax.i8 minmax.i16 minmax.i32 minmax.u8 minmax.u16 minmax.u32 minmax.usize minmax.i64 minmax.u64
/** `min` and `max`: JS `<=` orders numbers and bigints as Rust orders integers. */
const minMax = <T extends number | bigint>() =>
  ({
    min: (a: T, b: T): T => (a <= b ? a : b), // #needs m.min
    max: (a: T, b: T): T => (a >= b ? a : b), // #needs m.max
  }) as const;

// #endregion

// #region methods.usize parse.usize
const small64 = (n: bigint): Usize =>
  n > 9007199254740991n ? panicWith(`usize value ${n} does not fit in 53 bits`) : (Number(n) as Usize);
// #endregion

// #region parseIntError parse.i8 parse.i16 parse.i32 parse.u8 parse.u16 parse.u32 parse.usize parse.i64 parse.u64
/** A `std::num::ParseIntError`. Nothing translated reads its `kind()`, so it carries nothing. */
export type ParseIntError = { readonly "purecrate.ParseIntError": true };
// #endregion

// #region parse.i8 parse.i16 parse.i32 parse.u8 parse.u16 parse.u32 parse.usize parse.i64 parse.u64
const PARSE_INT_ERROR = Object.freeze({}) as ParseIntError;

/**
 * `s.parse::<T>()` into an integer: Rust's `from_str_radix(s, 10)`. An
 * optional `+`, or `-` for a signed type, then one or more ASCII digits,
 * in `lo..=hi`; `to` makes the runtime value. Anything else is `Err`.
 */
const parser =
  <T>(lo: bigint, hi: bigint, signed: boolean, to: (n: bigint) => T) =>
  (s: string): Result<T, ParseIntError> => {
    const digits = s.startsWith("+") || (signed && s.startsWith("-")) ? s.slice(1) : s;
    if (!/^[0-9]+$/.test(digits)) return { kind: "Err", error: PARSE_INT_ERROR };
    const n = s.startsWith("-") ? -BigInt(digits) : BigInt(digits);
    return n < lo || n > hi ? { kind: "Err", error: PARSE_INT_ERROR } : { kind: "Ok", value: to(n) };
  };
// #endregion

// #region bits.i8 bits.i16 bits.i32 bits.u8 bits.u16 bits.u32 bits.i64 bits.u64
/**
 * The amount of a shift, of any integer type. A debug build panics unless it
 * is in `0..bits`, comparing the whole value (so `-1` and `2^32 + 1` panic);
 * bits shifted out of the result are dropped without a panic.
 */
const shiftAmount = (n: number | bigint, bits: number, what: string): number =>
  n < 0 || n >= bits ? panic(`shift ${what} with overflow`) : Number(n);
// #endregion

// #region bits.i8 bits.i16 bits.i32 bits.u8 bits.u16 bits.u32
/**
 * `& | ^ ! << >>` on a width of at most 32 bits. The JS operators work on
 * int32; `wrap` sign- or zero-extends the low `bits` back into the width.
 */
const bits32 = <T extends number>(bits: number, signed: boolean) => {
  const s = 32 - bits;
  const wrap = (n: number): T => (signed ? (n << s) >> s : (n << s) >>> s) as T;
  return {
    and: (a: T, b: T): T => wrap(a & b),
    or: (a: T, b: T): T => wrap(a | b),
    xor: (a: T, b: T): T => wrap(a ^ b),
    not: (a: T): T => wrap(~a),
    shl: (a: T, n: number | bigint): T => wrap(a << shiftAmount(n, bits, "left")),
    shr: (a: T, n: number | bigint): T => {
      const k = shiftAmount(n, bits, "right");
      return wrap(signed ? a >> k : a >>> k);
    },
  } as const;
};
// #endregion

// #region bits.i64 bits.u64
/** `& | ^ ! << >>` on 64 bits. `bigint` `>>` is arithmetic, as Rust's is on `i64`. */
const bits64 = <T extends bigint>(signed: boolean) => {
  const wrap = (n: bigint): T => (signed ? BigInt.asIntN(64, n) : BigInt.asUintN(64, n)) as T;
  const v = (x: T): bigint => x as bigint;
  return {
    and: (a: T, b: T): T => wrap(v(a) & v(b)),
    or: (a: T, b: T): T => wrap(v(a) | v(b)),
    xor: (a: T, b: T): T => wrap(v(a) ^ v(b)),
    not: (a: T): T => wrap(~v(a)),
    shl: (a: T, n: number | bigint): T => wrap(v(a) << BigInt(shiftAmount(n, 64, "left"))),
    shr: (a: T, n: number | bigint): T => wrap(v(a) >> BigInt(shiftAmount(n, 64, "right"))),
  } as const;
};
// #endregion

// #region parseJson JsonFloat
const INTEGER_LITERAL = /^-?(?:0|[1-9]\d*)$/;

/**
 * A JSON number written with a fraction or an exponent, or `-0`, whose value
 * is integral (`50.0`, `5e1`). serde_json reads such a number as a float
 * only, so an integer field refuses it; `JSON.parse` gives `50` for `50.0`
 * and `50`, so `parseJson` hands it on in this box, which the `f32` / `f64`
 * schemas open and the integer schemas refuse.
 */
export class JsonFloat {
  readonly value: number;
  constructor(value: number) {
    this.value = value;
  }
}

/**
 * The objects and arrays of valid JSON `text` as a tree that `JSON.parse`'s
 * result can be walked beside: each node's children by key (the last of a
 * key written twice, the one `JSON.parse` keeps) or index, and the keys an
 * object holds twice.
 */
type Shape = { twice?: Set<string>; kids: Map<string | number, Shape> };
const shapeOf = (text: string): Shape | undefined => {
  // One entry per open bracket: the node, the keys seen in an object (`null`
  // in an array), the key a value goes under, and an array's index.
  const open: { node: Shape; seen: Set<string> | null; key: string | number }[] = [];
  let root: Shape | undefined;
  let atKey = false;
  const enter = (node: Shape): void => {
    const top = open[open.length - 1];
    if (top === undefined) root = node;
    else top.node.kids.set(top.key, node);
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    const top = open[open.length - 1];
    if (c === '"') {
      let j = i + 1;
      while (text[j] !== '"') j += text[j] === "\\" ? 2 : 1;
      if (atKey && top?.seen) {
        const key = JSON.parse(text.slice(i, j + 1)) as string;
        if (top.seen.has(key)) (top.node.twice ??= new Set()).add(key);
        top.seen.add(key);
        top.key = key;
        atKey = false;
      }
      i = j;
    } else if (c === "{" || c === "[") {
      const node: Shape = { kids: new Map() };
      enter(node);
      open.push({ node, seen: c === "{" ? new Set() : null, key: 0 });
      atKey = c === "{";
    } else if (c === "}" || c === "]") {
      open.pop();
    } else if (c === "," && top !== undefined) {
      if (top.seen === null) top.key = (top.key as number) + 1;
      else atKey = true;
    }
  }
  return root;
};

/** What `parseJson` saw in an object that `JSON.parse` does not keep. */
export type JsonKeys = Readonly<{ twice: ReadonlySet<string>; lone: boolean }>;
// A symbol property, not a `WeakMap` entry: arktype runs a morph on a copy
// of its input, which keeps the property but is not the key of an entry.
const KEYS: unique symbol = Symbol("purecrate.jsonKeys");

/**
 * The keys an object `parseJson` read held twice, and whether one held a
 * lone surrogate. serde refuses either in an object it reads (a field
 * twice, a key it cannot decode), and reads past both in a value it
 * ignores; so a schema asks for the objects it reads, and only those.
 */
export const jsonKeys = (x: object): JsonKeys | undefined => (x as { [KEYS]?: JsonKeys })[KEYS];

const LONE_KEY = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/;

/**
 * JSON text read as serde_json reads it, where `JSON.parse` would read it
 * differently:
 * - an integer literal outside ±(2^53−1) becomes a `bigint` with its exact
 *   value (serde_json writes `i64` and `u64` as JSON numbers; `JSON.parse`
 *   would round them);
 * - an integral number written as a float (`50.0`, `5e1`, `-0`) becomes a
 *   `JsonFloat`, which only a float field reads;
 * - an object that holds a key twice (`JSON.parse` keeps the last), or a
 *   key with a lone surrogate, is noted (`jsonKeys`), for the schema that
 *   reads it to refuse as serde does.
 *
 * The first two need a runtime that passes the literal's source text to the
 * reviver (Node 21+). Elsewhere a large number stays rounded, and the
 * `i64`/`u64` schemas reject it instead of reading a wrong value.
 */
export const parseJson = (text: string): unknown => {
  const value: unknown = JSON.parse(text, (_key: string, v: unknown, context?: { source?: string }) => {
    if (typeof v !== "number" || context?.source === undefined) return v;
    const integer = INTEGER_LITERAL.test(context.source) && context.source !== "-0";
    if (integer) return Number.isSafeInteger(v) ? v : BigInt(context.source);
    return Number.isInteger(v) || Object.is(v, -0) ? new JsonFloat(v) : v;
  });
  const note = (v: unknown, shape: Shape | undefined): void => {
    if (typeof v !== "object" || v === null || v instanceof JsonFloat || shape === undefined) return;
    if (Array.isArray(v)) {
      v.forEach((x, i) => note(x, shape.kids.get(i)));
      return;
    }
    const keys = Object.keys(v);
    const lone = keys.some((k) => LONE_KEY.test(k));
    if (shape.twice !== undefined || lone) {
      Object.defineProperty(v, KEYS, { value: { twice: shape.twice ?? new Set(), lone } satisfies JsonKeys });
    }
    for (const k of keys) note((v as Record<string, unknown>)[k], shape.kids.get(k));
  };
  note(value, shapeOf(text));
  return value;
};

/**
 * Where a schema reads `x` as a struct with `fields`: what serde says of it
 * that the shape alone does not, or `undefined`. A field twice is refused,
 * a key that cannot be decoded too; `fields` absent means every key is
 * read (an enum's one-key wrapper). A JSON array of as many elements as
 * `fields` is the struct's sequence form, which serde reads in field order.
 */
export const structIssue = (x: unknown, fields?: readonly string[]): string | undefined => {
  if (typeof x !== "object" || x === null) return undefined;
  const keys = jsonKeys(x);
  if (keys === undefined) return undefined;
  if (keys.lone) return "a key with a lone surrogate";
  for (const k of keys.twice) if (fields === undefined || fields.includes(k)) return `duplicate field \`${k}\``;
  return undefined;
};

/** A struct's sequence form, `[a, b]`, as the object serde reads it to. */
export const fromSequence = (x: unknown, fields: readonly string[]): unknown =>
  Array.isArray(x) && x.length === fields.length ? Object.fromEntries(fields.map((f, i) => [f, x[i]])) : x;
// #endregion

/**
 * `str` operations whose result depends on the encoding (design/01 §6).
 * Rust counts and indexes a string in UTF-8 bytes; JS in UTF-16 units. The
 * string must be well-formed: a lone surrogate is not a Rust `String`, and
 * its bytes here are not specified.
 */
// #region str.wellFormed
/** The objects and arrays `Str.wellFormed` has found free of lone surrogates. */
const wellFormedSeen = new WeakSet<object>();
// #endregion
export const Str = {
  // #region str.bytes
  /** `str::as_bytes`: the UTF-8 bytes. */
  bytes: (s: string): ReadonlyArray<U8> => {
    const out: number[] = [];
    for (const c of s) {
      const p = c.codePointAt(0) as number;
      if (p < 0x80) out.push(p);
      else if (p < 0x800) out.push(0xc0 | (p >> 6), 0x80 | (p & 0x3f));
      else if (p < 0x10000) out.push(0xe0 | (p >> 12), 0x80 | ((p >> 6) & 0x3f), 0x80 | (p & 0x3f));
      else out.push(0xf0 | (p >> 18), 0x80 | ((p >> 12) & 0x3f), 0x80 | ((p >> 6) & 0x3f), 0x80 | (p & 0x3f));
    }
    return out as unknown as ReadonlyArray<U8>;
  },
  // #endregion
  // #region str.len
  /** `str::len`: the number of UTF-8 bytes. */
  len: (s: string): Usize => utf8Len(s),
  // #endregion
  // #region str.slice
  /**
   * `&s[start..end]` at UTF-8 byte positions (`end` absent for `&s[start..]`).
   * Panics as Rust does, in its order: a position past the end, a reversed
   * range, then a position inside a character, shown as `Debug` shows it.
   */
  slice: (s: string, start: Usize, end?: Usize): string => {
    const len = utf8Len(s);
    const stop = end ?? len;
    if (start > len) panicWith(`start byte index ${start} is out of bounds for string of length ${len}`);
    if (stop > len) panicWith(`end byte index ${stop} is out of bounds for string of length ${len}`);
    if (start > stop) panicWith(`byte range starts at ${start} but ends at ${stop}`);
    let byte = 0;
    let unit = 0;
    let from = -1;
    let to = -1;
    let inside: string | null = null;
    for (const c of s) {
      const w = utf8Width(c);
      if (byte === start) from = unit;
      if (byte === stop) to = unit;
      for (const [which, at] of [["start", start], ["end", stop]] as const) {
        if (inside === null && at > byte && at < byte + w) {
          inside = `${which} byte index ${at} is not a char boundary; it is inside '${debugChar(c)}' (bytes ${byte}..${byte + w} of string)`;
        }
      }
      byte += w;
      unit += c.length;
    }
    if (byte === start) from = unit;
    if (byte === stop) to = unit;
    if (from < 0 || to < 0) panicWith(inside as string);
    return s.slice(from, to);
  },
  // #endregion
  // #region str.wellFormed
  /**
   * A `pub` function's argument checked on entry: a lone surrogate is in no
   * Rust `str`, so the call panics here, wherever in the value the string
   * is (a field, a variant's payload, an element, an `Option`). An object or
   * array checked once is not walked again (`wellFormedSeen`): a state passed
   * back on every call costs only its new parts.
   */
  wellFormed: (x: unknown): void => {
    const lone = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/;
    const visit = (v: unknown): void => {
      if (typeof v === "string") {
        if (lone.test(v)) panicWith("a string holds a lone surrogate, which no Rust `str` does");
      } else if (typeof v === "object" && v !== null && !wellFormedSeen.has(v)) {
        for (const e of Array.isArray(v) ? v : Object.values(v)) visit(e);
        wellFormedSeen.add(v);
      }
    };
    visit(x);
  },
  // #endregion
  // #region str.stripPrefix
  /** `str::strip_prefix` with a `&str`. */
  stripPrefix: (s: string, p: string): string | null => (s.startsWith(p) ? s.slice(p.length) : null),
  // #endregion
  // #region str.stripSuffix
  /** `str::strip_suffix` with a `&str`. */
  stripSuffix: (s: string, p: string): string | null => (s.endsWith(p) ? s.slice(0, s.length - p.length) : null),
  // #endregion
  // #region str.splitOnce
  /** `str::split_once` with a `char` or a `&str`: the text around the first match. */
  splitOnce: (s: string, p: string): readonly [string, string] | null => {
    const i = s.indexOf(p);
    return i < 0 ? null : [s.slice(0, i), s.slice(i + p.length)];
  },
  // #endregion
  // #region str.eqIgnoreAsciiCase
  /**
   * `str::eq_ignore_ascii_case`: equal once ASCII `A`..=`Z` are folded to
   * lower case; every other unit compares as it is (no Unicode folding).
   */
  eqIgnoreAsciiCase: (a: string, b: string): boolean => {
    if (a.length !== b.length) return false;
    const fold = (u: number): number => (u >= 65 && u <= 90 ? u + 32 : u);
    for (let i = 0; i < a.length; i++) {
      if (fold(a.charCodeAt(i)) !== fold(b.charCodeAt(i))) return false;
    }
    return true;
  },
  // #endregion
  // #region str.cmp ord.cmpStr
  /**
   * `Ord for str`: -1, 0, or 1 by code point, as Rust's UTF-8 bytes order.
   * JS `<` compares UTF-16 units, which puts U+E000..=U+FFFF above the
   * surrogates of the supplementary planes; at the first unit that differs,
   * those are moved back below them. A shorter prefix orders first.
   */
  cmp: (a: string, b: string): -1 | 0 | 1 => {
    const key = (u: number): number => (u < 0xd800 ? u : u < 0xe000 ? u + 0x2000 : u - 0x800);
    const n = a.length < b.length ? a.length : b.length;
    for (let i = 0; i < n; i++) {
      const x = a.charCodeAt(i);
      const y = b.charCodeAt(i);
      if (x !== y) return key(x) < key(y) ? -1 : 1;
    }
    return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
  },
  // #endregion
} as const;

// #region ord.cmp ord.cmpStr ord.then ord.cmpList
/** std's `Ordering`, as the crate's `Ordering` declares it. */
type Ordering = Readonly<{ kind: "Less" }> | Readonly<{ kind: "Equal" }> | Readonly<{ kind: "Greater" }>;
// #endregion

// #region ord.cmp ord.cmpStr ord.cmpList
const ORDERINGS: readonly [Ordering, Ordering, Ordering] = [{ kind: "Less" }, { kind: "Equal" }, { kind: "Greater" }];
// #endregion

/** `cmp` and `Ordering::then`, giving std's `Ordering`. */
export const Ord = {
  // #region ord.cmp
  /** `a.cmp(&b)` on an integer or `bool`: JS `<` orders them as Rust does. */
  cmp: <T extends number | bigint | boolean>(a: T, b: T): Ordering => ORDERINGS[a < b ? 0 : a === b ? 1 : 2],
  // #endregion
  // #region ord.cmpStr
  /** `a.cmp(&b)` on a `char`, a string, or a `Uuid`: by code point. */
  cmpStr: (a: string, b: string): Ordering => ORDERINGS[Str.cmp(a, b) + 1],
  // #endregion
  // #region ord.cmpList
  /**
   * `a.cmp(&b)` on two `Vec`s: the first pair of elements `by` does not find
   * equal decides, else the shorter is less, as std orders slices.
   */
  cmpList: <T>(a: ReadonlyArray<T>, b: ReadonlyArray<T>, by: (x: T, y: T) => Ordering): Ordering => {
    const n = Math.min(a.length, b.length);
    for (let i = 0; i < n; i++) {
      const o = by(a[i] as T, b[i] as T);
      if (o.kind !== "Equal") return o;
    }
    return ORDERINGS[a.length < b.length ? 0 : a.length === b.length ? 1 : 2];
  },
  // #endregion
  // #region ord.then
  /** `o.then(p)`: `p` when `o` is `Equal`, else `o`. */
  then: (o: Ordering, p: Ordering): Ordering => (o.kind === "Equal" ? p : o),
  // #endregion
} as const;

/**
 * The consuming iterator methods, as std's default methods run them: in
 * order, `all` stopping at the first `false`, `any` and `position` at the
 * first `true`. `sum` adds from `zero` with `add`, the type's checked
 * addition, so it panics where a debug build does.
 */
export const Iter = {
  // #region iter.all
  all: <T>(xs: Iterable<T>, f: (x: T) => boolean): boolean => {
    for (const x of xs) if (!f(x)) return false;
    return true;
  },
  // #endregion
  // #region iter.any
  any: <T>(xs: Iterable<T>, f: (x: T) => boolean): boolean => {
    for (const x of xs) if (f(x)) return true;
    return false;
  },
  // #endregion
  // #region iter.position
  position: <T>(xs: Iterable<T>, f: (x: T) => boolean): Usize | null => {
    let i = 0;
    for (const x of xs) {
      if (f(x)) return i as Usize;
      i++;
    }
    return null;
  },
  // #endregion
  // #region iter.count
  count: (xs: Iterable<unknown>): Usize => {
    let n = 0;
    for (const x of xs) {
      void x;
      n++;
    }
    return n as Usize;
  },
  // #endregion
  // #region iter.sum
  sum: <T>(xs: Iterable<T>, add: (a: T, b: T) => T, zero: T): T => {
    let total = zero;
    for (const x of xs) total = add(total, x);
    return total;
  },
  // #endregion
  // #region iter.map
  /** `.map(f)`: lazy, so `f` runs on an item when the consumer reaches it, as in Rust. */
  map: function* <T, U>(xs: Iterable<T>, f: (x: T) => U): Generator<U, void, undefined> {
    for (const x of xs) yield f(x);
  },
  // #endregion
  // #region iter.filter
  /** `.filter(p)`: lazy, as `map`. */
  filter: function* <T>(xs: Iterable<T>, p: (x: T) => boolean): Generator<T, void, undefined> {
    for (const x of xs) if (p(x)) yield x;
  },
  // #endregion
  // #region iter.tryCollect
  /** `collect::<Result<Vec<T>, E>>()` after `map(f)`: stops at the first `Err`. */
  tryCollect: <X, T, E>(xs: Iterable<X>, f: (x: X) => Result<T, E>): Result<ReadonlyArray<T>, E> => {
    const out: T[] = [];
    for (const x of xs) {
      const r = f(x);
      if (r.kind === "Err") return r;
      out.push(r.value);
    }
    return Result.ok(out);
  },
  // #endregion
} as const;

/** Indexing and slicing a `Vec<T>` or `&[T]`, panicking where Rust panics. */
export const Slice = {
  // #region slice.at
  /** `xs[i]`. */
  at: <T>(xs: ReadonlyArray<T>, i: number): T => {
    if (!Number.isInteger(i) || i < 0 || i >= xs.length) {
      throw new Panic(`index out of bounds: the len is ${xs.length} but the index is ${i}`);
    }
    return xs[i] as T;
  },
  // #endregion
  // #region slice.range
  /**
   * `&xs[a..b]`, with `null` for an open end (`&xs[a..]`, `&xs[..b]`).
   * Checks the start, then the end, then their order, as Rust reports them.
   */
  range: <T>(xs: ReadonlyArray<T>, a: number | null, b: number | null): ReadonlyArray<T> => {
    if (a !== null && a > xs.length) throw new Panic(`range start index ${a} out of range for slice of length ${xs.length}`);
    if (b !== null && b > xs.length) throw new Panic(`range end index ${b} out of range for slice of length ${xs.length}`);
    if (a !== null && b !== null && a > b) throw new Panic(`slice index starts at ${a} but ends at ${b}`);
    return xs.slice(a ?? 0, b ?? xs.length);
  },
  // #endregion
  // #region slice.insert
  /** `v.insert(i, x)` on a local's own array. */
  insert: <T>(xs: T[], i: Usize, x: T): void => {
    if (i > xs.length) throw new Panic(`insertion index (is ${i}) should be <= len (is ${xs.length})`);
    xs.splice(i, 0, x);
  },
  // #endregion
  // #region slice.remove
  /** `v.remove(i)` on a local's own array. */
  remove: <T>(xs: T[], i: Usize): T => {
    if (i >= xs.length) throw new Panic(`removal index (is ${i}) should be < len (is ${xs.length})`);
    return xs.splice(i, 1)[0] as T;
  },
  // #endregion
  // #region slice.set
  /** `v[i] = x` on a local's own array, which JS would grow past its end. */
  set: <T>(xs: T[], i: Usize, x: T): void => {
    if (i >= xs.length) throw new Panic(`index out of bounds: the len is ${xs.length} but the index is ${i}`);
    xs[i] = x;
  },
  // #endregion
} as const;

// #region str.slice
/**
 * A non-ASCII `char` as Rust's `Debug` writes it between quotes: `\u{..}`
 * for a grapheme extender or a code point that is not printable (the
 * categories core's `printable.py` escapes), itself otherwise. The tables are
 * the JS engine's; they agree with Rust's where both use one Unicode version
 * (design/01 §3).
 */
const debugChar = (c: string): string =>
  (escaped ??= new RegExp("[\\p{Grapheme_Extend}\\p{Zs}\\p{Zl}\\p{Zp}\\p{Cc}\\p{Cf}\\p{Cs}\\p{Co}\\p{Cn}]", "u")).test(c) && c !== " "
    ? `\\u{${(c.codePointAt(0) as number).toString(16)}}`
    : c;
// Built on first use: a literal with Unicode properties costs about half a
// millisecond when the module loads, for a message only a panic prints.
let escaped: RegExp | undefined;
// #endregion

// #region str.len str.slice
const utf8Len = (s: string): Usize => {
  let n = 0;
  for (const c of s) n += utf8Width(c);
  return n as Usize;
};

const utf8Width = (c: string): number => {
  const p = c.codePointAt(0) as number;
  return p < 0x80 ? 1 : p < 0x800 ? 2 : p < 0x10000 ? 3 : 4;
};
// #endregion

// #region char
const code = (c: Char): number => c.codePointAt(0) as number;
const within = (c: Char, lo: number, hi: number): boolean => code(c) >= lo && code(c) <= hi;
const upper = (c: Char): boolean => within(c, 0x41, 0x5a);
const lower = (c: Char): boolean => within(c, 0x61, 0x7a);
const digit = (c: Char): boolean => within(c, 0x30, 0x39);
const radix = (r: U32): number =>
  r < 2 || r > 36 ? panicWith("to_digit: invalid radix -- radix must be in the range 2 to 36 inclusive") : r;
// #endregion
// #region char methods.usize parse.usize str.slice str.wellFormed
const panicWith = (message: string): never => {
  throw new Panic(message);
};
// #endregion
// #region char
const digitValue = (c: Char, r: U32): number | null => {
  const base = radix(r);
  const p = code(c);
  const d = p >= 0x30 && p <= 0x39 ? p - 0x30 : (p | 0x20) >= 0x61 && (p | 0x20) <= 0x7a ? (p | 0x20) - 0x61 + 10 : 99;
  return d < base ? d : null;
};
// #endregion

/**
 * `char` operations (design/01 §6). Ordering and ranges go through `code`:
 * JS orders strings by UTF-16 unit, which puts U+E000..=U+FFFF above the
 * supplementary planes. Only ASCII and code-point methods are here; the
 * Unicode-table ones (`is_alphabetic`, ...) are not.
 */
export const Char = {
  // #region char.is
  /** Checks `s` is one Unicode scalar value, as serde reads a `char`. */
  is: (s: string): s is Char => {
    const p = s.codePointAt(0);
    return p !== undefined && s.length === (p > 0xffff ? 2 : 1) && (p < 0xd800 || p > 0xdfff);
  },
  // #endregion
  // #region char
  /** `u32::from(c)`: the code point. */
  code: (c: Char): U32 => code(c) as U32,
  /** `char::from(b)`: U+0000..=U+00FF. */
  fromU8: (b: U8): Char => String.fromCharCode(b) as Char,
  /** `char::from_u32(n)`: `None` for a surrogate or past U+10FFFF. */
  fromU32: (n: U32): Char | null =>
    (n >= 0xd800 && n <= 0xdfff) || n > 0x10ffff ? null : (String.fromCodePoint(n) as Char),
  isAscii: (c: Char): boolean => code(c) < 0x80,
  isAsciiAlphabetic: (c: Char): boolean => upper(c) || lower(c),
  isAsciiAlphanumeric: (c: Char): boolean => upper(c) || lower(c) || digit(c),
  isAsciiControl: (c: Char): boolean => code(c) < 0x20 || code(c) === 0x7f,
  isAsciiDigit: digit,
  isAsciiGraphic: (c: Char): boolean => within(c, 0x21, 0x7e),
  isAsciiHexdigit: (c: Char): boolean => digit(c) || within(c, 0x41, 0x46) || within(c, 0x61, 0x66),
  isAsciiLowercase: lower,
  isAsciiPunctuation: (c: Char): boolean =>
    within(c, 0x21, 0x2f) || within(c, 0x3a, 0x40) || within(c, 0x5b, 0x60) || within(c, 0x7b, 0x7e),
  isAsciiUppercase: upper,
  /** Space, tab, LF, FF, CR. Not VT (U+000B), unlike JS `\s`. */
  isAsciiWhitespace: (c: Char): boolean => [0x20, 0x09, 0x0a, 0x0c, 0x0d].includes(code(c)),
  toAsciiLowercase: (c: Char): Char => (upper(c) ? (String.fromCharCode(code(c) + 32) as Char) : c),
  toAsciiUppercase: (c: Char): Char => (lower(c) ? (String.fromCharCode(code(c) - 32) as Char) : c),
  eqIgnoreAsciiCase: (a: Char, b: Char): boolean => Char.toAsciiLowercase(a) === Char.toAsciiLowercase(b),
  /** `char::len_utf8`: 1 to 4. */
  lenUtf8: (c: Char): Usize => (code(c) < 0x80 ? 1 : code(c) < 0x800 ? 2 : code(c) < 0x10000 ? 3 : 4) as Usize,
  /** ASCII digits and letters only, as Rust; panics on a radix outside 2..=36. */
  isDigit: (c: Char, r: U32): boolean => digitValue(c, r) !== null,
  toDigit: (c: Char, r: U32): U32 | null => digitValue(c, r) as U32 | null,
  // #endregion
} as const;

// #region Uuid
/**
 * A `uuid::Uuid`, always in the lowercase hyphenated form (8-4-4-4-12) that
 * serde writes. In that form `===` is Rust's `==`, and string order is the
 * order of the 16 bytes, as the hyphens sit at the same places in both.
 */
export type Uuid = string & { readonly "purecrate.Uuid": true };
// #endregion
// #region UuidError
/** A `uuid::Error`. Nothing translated reads one, so it carries nothing. */
export type UuidError = { readonly "purecrate.UuidError": true };
// #endregion

// #region uuid
const UUID_ERROR = Object.freeze({}) as UuidError;
const HEX32 = /^[0-9a-fA-F]{32}$/;
const HYPHENATED = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

/**
 * The 32 hex digits of what `uuid`'s parser accepts, chosen by length as it
 * does: simple (32), hyphenated (36), braced (38), `urn:uuid:` (45; the
 * prefix in lowercase only). Rust measures in UTF-8 bytes and JS in UTF-16
 * units, but any non-ASCII character fails the hex check either way.
 */
const uuidDigits = (s: string): string | null => {
  if (s.length === 32) return HEX32.test(s) ? s : null;
  const body =
    s.length === 36
      ? s
      : s.length === 38 && s.startsWith("{") && s.endsWith("}")
        ? s.slice(1, 37)
        : s.length === 45 && s.startsWith("urn:uuid:")
          ? s.slice(9)
          : null;
  return body !== null && HYPHENATED.test(body) ? body.replaceAll("-", "") : null;
};

/** `uuid::Uuid` operations (design/01 §6). */
export const Uuid = {
  /**
   * `Uuid::parse_str` (and `try_parse`): the canonical form of any string
   * the `uuid` crate reads, in any case; `Err` otherwise. Shaped as the
   * generated `Result`.
   */
  parseStr: (s: string): Readonly<{ kind: "Ok"; value: Uuid }> | Readonly<{ kind: "Err"; error: UuidError }> => {
    const d = uuidDigits(s)?.toLowerCase();
    return d === undefined
      ? { kind: "Err", error: UUID_ERROR }
      : {
          kind: "Ok",
          value: `${d.slice(0, 8)}-${d.slice(8, 12)}-${d.slice(12, 16)}-${d.slice(16, 20)}-${d.slice(20)}` as Uuid,
        };
  },
  /** `Uuid::nil()`. */
  nil: (): Uuid => "00000000-0000-0000-0000-000000000000" as Uuid,
} as const;
// #endregion

/** Integer and float widths. Domain packages and schema adapters share these brands. */
export const Int = {
  // #region int.i8
  i8: {
    ...small<I8>(-128, 127),
    ...bits32<I8>(8, true), // #needs bits.i8
    ...minMax<I8>(), // #needs minmax.i8
    ...methods({ lo: -128n, hi: 127n, bits: 8, signed: true, to: (n) => Number(n) as I8 }), // #needs methods.i8
    parse: parser(-128n, 127n, true, (n) => Number(n) as I8), // #needs parse.i8
  },
  // #endregion
  // #region int.i16
  i16: {
    ...small<I16>(-32768, 32767),
    ...bits32<I16>(16, true), // #needs bits.i16
    ...minMax<I16>(), // #needs minmax.i16
    ...methods({ lo: -32768n, hi: 32767n, bits: 16, signed: true, to: (n) => Number(n) as I16 }), // #needs methods.i16
    parse: parser(-32768n, 32767n, true, (n) => Number(n) as I16), // #needs parse.i16
  },
  // #endregion
  // #region int.i32
  i32: {
    ...small<I32>(-2147483648, 2147483647),
    ...bits32<I32>(32, true), // #needs bits.i32
    ...minMax<I32>(), // #needs minmax.i32
    ...methods({ lo: -2147483648n, hi: 2147483647n, bits: 32, signed: true, to: (n) => Number(n) as I32 }), // #needs methods.i32
    parse: parser(-2147483648n, 2147483647n, true, (n) => Number(n) as I32), // #needs parse.i32
  },
  // #endregion
  // #region int.u8
  u8: {
    ...small<U8>(0, 255),
    ...bits32<U8>(8, false), // #needs bits.u8
    ...minMax<U8>(), // #needs minmax.u8
    ...methods({ lo: 0n, hi: 255n, bits: 8, signed: false, to: (n) => Number(n) as U8 }), // #needs methods.u8
    parse: parser(0n, 255n, false, (n) => Number(n) as U8), // #needs parse.u8
  },
  // #endregion
  // #region int.u16
  u16: {
    ...small<U16>(0, 65535),
    ...bits32<U16>(16, false), // #needs bits.u16
    ...minMax<U16>(), // #needs minmax.u16
    ...methods({ lo: 0n, hi: 65535n, bits: 16, signed: false, to: (n) => Number(n) as U16 }), // #needs methods.u16
    parse: parser(0n, 65535n, false, (n) => Number(n) as U16), // #needs parse.u16
  },
  // #endregion
  // #region int.u32
  u32: {
    ...small<U32>(0, 4294967295),
    ...bits32<U32>(32, false), // #needs bits.u32
    ...minMax<U32>(), // #needs minmax.u32
    ...methods({ lo: 0n, hi: 4294967295n, bits: 32, signed: false, to: (n) => Number(n) as U32 }), // #needs methods.u32
    parse: parser(0n, 4294967295n, false, (n) => Number(n) as U32), // #needs parse.u32
  },
  // #endregion
  // #region int.usize
  // No bitwise operators: Rust's `usize` has 64 bits, this one 53. Its
  // methods work in Rust's 64 bits and throw on a result above 2^53−1.
  usize: {
    ...small<Usize>(0, 9007199254740991),
    ...minMax<Usize>(), // #needs minmax.usize
    ...methods({ lo: 0n, hi: 18446744073709551615n, bits: 64, signed: false, to: small64 }), // #needs methods.usize
    parse: parser(0n, 18446744073709551615n, false, small64), // #needs parse.usize
  },
  // #endregion
  // #region int.i64
  i64: {
    ...big<I64>(-9223372036854775808n, 9223372036854775807n),
    ...bits64<I64>(true), // #needs bits.i64
    ...minMax<I64>(), // #needs minmax.i64
    ...methods({ lo: -9223372036854775808n, hi: 9223372036854775807n, bits: 64, signed: true, to: (n) => n as I64 }), // #needs methods.i64
    parse: parser(-9223372036854775808n, 9223372036854775807n, true, (n) => n as I64), // #needs parse.i64
  },
  // #endregion
  // #region int.u64
  u64: {
    ...big<U64>(0n, 18446744073709551615n),
    ...bits64<U64>(false), // #needs bits.u64
    ...minMax<U64>(), // #needs minmax.u64
    ...methods({ lo: 0n, hi: 18446744073709551615n, bits: 64, signed: false, to: (n) => n as U64 }), // #needs methods.u64
    parse: parser(0n, 18446744073709551615n, false, (n) => n as U64), // #needs parse.u64
  },
  // #endregion
  // #region int.f32
  f32: {
    of: (value: number): F32 => Math.fround(value) as F32,
  },
  // #endregion
  // #region int.f64
  f64: {
    of: (value: number): F64 => value as F64,
  },
  // #endregion
} as const;

// #region json
/** Shortest digits and decimal exponent: `digits` × 10^(`point` − length). */
const decimal = (x: number): { digits: string; point: number } => {
  const [mantissa, exponent] = x.toExponential().split("e");
  return { digits: mantissa.replace("-", "").replace(".", ""), point: Number(exponent) + 1 };
};

/**
 * A finite float laid out as ryu writes it for serde_json: `1.0`, `0.001`,
 * `1e16`, `1.5e-7`. Plain notation holds for 10^(`low`) ≤ |x| < 10^`high`.
 */
const ryu = (x: number, digits: string, point: number, high: number, low: number): string => {
  const sign = x < 0 || Object.is(x, -0) ? "-" : "";
  if (x === 0) return `${sign}0.0`;
  const length = digits.length;
  if (point >= length && point <= high) return `${sign}${digits}${"0".repeat(point - length)}.0`;
  if (point > 0 && point <= high) return `${sign}${digits.slice(0, point)}.${digits.slice(point)}`;
  if (point > low && point <= 0) return `${sign}0.${"0".repeat(-point)}${digits}`;
  const rest = length === 1 ? "" : `.${digits.slice(1)}`;
  return `${sign}${digits[0]}${rest}e${point - 1}`;
};

/**
 * Writes domain values as serde_json writes the Rust value (design/04 §6):
 * integers exactly (`bigint` included), floats as ryu lays them out, and
 * non-finite floats as `null`, which serde_json then cannot read back.
 * Generated `toJson` encoders compose these.
 */
export const Json = {
  /**
   * `{"k":v,..}` from each key and its value's JSON text, in order: a
   * struct's fields as serde writes them, or a variant's wrapper. The keys
   * are Rust identifiers, which need no escaping.
   */
  object: (pairs: ReadonlyArray<readonly [string, string]>): string =>
    `{${pairs.map(([k, v]) => `"${k}":${v}`).join(",")}}`,
  /** `[a,b,..]` from each element's JSON text: a tuple or a tuple variant. */
  tuple: (items: ReadonlyArray<string>): string => `[${items.join(",")}]`,
  int: (n: number | bigint): string => String(n),
  bool: (b: boolean): string => (b ? "true" : "false"),
  /** JSON.stringify escapes as serde_json does for well-formed strings. */
  str: (s: string): string => JSON.stringify(s),
  f64: (x: number): string => {
    if (!Number.isFinite(x)) return "null";
    const { digits, point } = decimal(x);
    return ryu(x, digits, point, 16, -5);
  },
  /**
   * The shortest digits that read back as the same `f32`. When two are
   * equally near, ryu takes the even one; `toPrecision` rounds half up.
   */
  f32: (x: number): string => {
    if (!Number.isFinite(x)) return "null";
    // At most 9 digits are needed; 100 give the exact value of any `f32`
    // whose expansion could end in a tie.
    const [exact, exponent] = Math.abs(x).toExponential(99).split("e");
    const all = exact.replace(".", "");
    for (let p = 1; p <= 9; p++) {
      const shorter = Number(x.toPrecision(p));
      if (Math.fround(shorter) !== x) continue;
      let digits = decimal(shorter).digits;
      let point = decimal(shorter).point;
      const tie = all[p] === "5" && /^0*$/.test(all.slice(p + 1));
      if (tie && Number(all[p - 1]) % 2 === 0) {
        const down = Number(`${x < 0 ? "-" : ""}${all[0]}.${all.slice(1, p)}e${exponent}`);
        if (Math.fround(down) === x) ({ digits, point } = decimal(down));
      }
      return ryu(x, digits, point, 13, -6);
    }
    return "null";
  },
  array: <T>(xs: ReadonlyArray<T>, write: (x: T) => string): string => `[${xs.map((x) => write(x)).join(",")}]`,
} as const;
// #endregion
